<?php $modules=[];foreach($permissions as $p)$modules[$p['module']][]=$p; ?>
<section class="page-header"><div><a class="back-link" href="<?= url('settings') ?>"><i class="fa-solid fa-arrow-left"></i> Back to settings</a><h1>Roles & Permissions</h1><p>Server-enforced module permissions. Super Admin always retains full access.</p></div></section><form method="post" action="<?= url('settings/roles') ?>"><?= csrf_field() ?><section class="panel permission-panel"><div class="table-scroll"><table class="permission-table"><thead><tr><th>Module / action</th><?php foreach($roles as $role):?><th><?= e($role['name']) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($modules as $module=>$items):?><tr class="permission-module"><td colspan="<?= count($roles)+1 ?>"><?= e(ucwords(str_replace('_',' ',$module))) ?></td></tr><?php foreach($items as $permission):?><tr><td><strong><?= e(ucfirst($permission['action'])) ?></strong><small><?= e($permission['slug']) ?></small></td><?php foreach($roles as $role):$super=$role['slug']==='super-admin';?><td><label class="permission-check"><input type="checkbox" name="permissions[<?= $role['id'] ?>][]" value="<?= $permission['id'] ?>" <?= $super||isset($matrix[$role['id']][$permission['id']])?'checked':'' ?> <?= $super?'disabled':'' ?>><i class="fa-solid fa-check"></i></label></td><?php endforeach;?></tr><?php endforeach;?><?php endforeach;?></tbody></table></div><div class="form-actions"><a class="button button-secondary" href="<?= url('settings') ?>">Cancel</a><button class="button button-primary"><i class="fa-solid fa-shield-halved"></i> Save permission matrix</button></div></section></form>
